-- Our own products, separate from client work in `projects`.
-- Everything here is managed from /admin/products. Logos and screenshots are
-- uploaded there. Copy below comes from each product's public website.

CREATE TABLE IF NOT EXISTS products (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name         VARCHAR(120) NOT NULL,
  slug         VARCHAR(190) NOT NULL,
  tagline      VARCHAR(200) NOT NULL,
  category     VARCHAR(120) NOT NULL,
  summary      VARCHAR(400) NOT NULL,
  description  TEXT NOT NULL,
  status       VARCHAR(20) NOT NULL DEFAULT 'live',
  website_url  VARCHAR(500) NULL DEFAULT NULL,
  android_url  VARCHAR(500) NULL DEFAULT NULL,
  ios_url      VARCHAR(500) NULL DEFAULT NULL,
  cta_label    VARCHAR(40) NOT NULL DEFAULT 'Try now',
  brand_color  VARCHAR(9) NOT NULL DEFAULT '#7c3aed',
  accent_color VARCHAR(9) NOT NULL DEFAULT '#ec4899',
  logo         VARCHAR(500) NULL DEFAULT NULL,
  hero_image   VARCHAR(500) NULL DEFAULT NULL,
  gallery      MEDIUMTEXT NOT NULL,
  content      MEDIUMTEXT NOT NULL,
  is_published TINYINT(1) NOT NULL DEFAULT 1,
  sort_order   INT NOT NULL DEFAULT 0,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uniq_products_slug (slug),
  KEY idx_products_published (is_published, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
;

INSERT INTO products (name, slug, tagline, category, summary, description, status, website_url, cta_label, brand_color, accent_color, gallery, content, is_published, sort_order) VALUES ('myGallaBook', 'mygallabook', 'GST and non-GST bills in 30 seconds', 'Billing & Business Software', 'Billing, stock, credit and GST reports in one app for small Indian businesses, on your phone and your computer.', 'myGallaBook is a GST billing, inventory and accounting app for shop owners, wholesalers and small manufacturers. Make bills, track stock, follow up on payments and keep your books clean from your phone or your computer, even when the internet is down.', 'live', 'https://mygallabook.com/', 'Try myGallaBook', '#0f6b52', '#f59e0b', '[]', '{"highlights":[{"value":"30 sec","label":"to make a bill"},{"value":"9","label":"Indian languages"},{"value":"3","label":"Android, iPhone, Windows"},{"value":"12","label":"business types with their own setup"}],"problems":[{"title":"Registers and Excel everywhere","text":"Bills, stock and udhaar end up in different notebooks and sheets, so the real picture of the shop is never in one place."},{"title":"GST takes too much time","text":"Working out HSN codes, tax splits and monthly reports by hand slows the counter down and invites mistakes."},{"title":"Money stuck with customers","text":"Without a simple way to follow up, pending payments are forgotten and cash flow suffers."}],"features":[{"title":"GST and non-GST invoices","text":"HSN codes and CGST, SGST or IGST are applied for you. Print the bill or send it on WhatsApp."},{"title":"Stock and inventory","text":"Stock goes down with every sale, and you get an alert when an item runs low."},{"title":"Payment reminders","text":"Remind customers who owe you by SMS or WhatsApp in one tap."},{"title":"UPI on every invoice","text":"Each invoice carries a QR code so customers can pay on the spot."},{"title":"GST reports for your CA","text":"Send GSTR-1, GSTR-3B and the sales register as Excel files."},{"title":"Works offline","text":"Keep billing without internet. Everything syncs when you are back online."},{"title":"Barcode scanning","text":"Print your own barcodes and add items to a bill by scanning them."},{"title":"E-invoice and e-way bill","text":"Generate GST e-invoices and e-way bills from the bill you just made."},{"title":"Staff logins and multi-device","text":"One account across phone and computer, with separate logins for your staff."}],"steps":[{"title":"Download the app","text":"Start on Android, Windows or in the browser."},{"title":"Add your business","text":"Enter your name, GSTIN and logo, and import items from Excel."},{"title":"Create and send the bill","text":"Pick a customer, add items and share the bill on WhatsApp."},{"title":"Check your reports","text":"See sales, stock and profit for the day before you close the shop."}],"audience":["Grocery and kirana","Pharmacy","Hardware","Garments","Electronics","Wholesale","Restaurant","Mobile shop","Stationery","Auto parts","Jewellery","Manufacturing"],"plans":[{"name":"Free","price":"₹0","note":"Start billing with no card","items":["GST billing","Inventory","Reports"]},{"name":"Silver","price":"See pricing","note":"For a single counter","items":["Sync across devices","3 companies","10 e-way bills a month","No ads on invoices","Export to Tally"]},{"name":"Gold","price":"See pricing","note":"For a growing business","items":["Sync across devices","5 companies","Unlimited e-way bills","No ads on invoices","Export to Tally"]}],"faqs":[{"question":"Does myGallaBook work without internet?","answer":"Yes. You can keep billing offline, and your bills sync when you reconnect."},{"question":"Can I use it on both my phone and computer?","answer":"Yes. One account works across Android, iPhone and Windows, so every device shows the same numbers."},{"question":"Can I make both GST and non-GST bills?","answer":"Yes. HSN codes and tax splits are handled for GST bills, and non-GST invoices are supported too."},{"question":"Can I bring in my existing data?","answer":"Yes. Items, parties and balances can be imported from your existing books or Excel."},{"question":"Can I take my data out?","answer":"Yes. You can export to Excel or PDF at any time."}]}', 1, 1);

INSERT INTO products (name, slug, tagline, category, summary, description, status, website_url, cta_label, brand_color, accent_color, gallery, content, is_published, sort_order) VALUES ('Apnajoda', 'apnajoda', 'Serious about finding someone?', 'Dating & Matchmaking App', 'A dating app for India where selfie-verified singles meet for a serious relationship or marriage.', 'Apnajoda is built for people who are done with casual swiping. Meet selfie-verified, marriage-minded singles, get daily picks, talk safely through in-app chat, voice and video calls, see Kundli Gun Milan and break the ice with a game of Ludo. It is free to join on the web and Android.', 'live', 'https://apnajoda.com/', 'Try Apnajoda', '#1f4e79', '#b3223f', '[]', '{"highlights":[{"value":"Free","label":"to join"},{"value":"Selfie","label":"verified members"},{"value":"2","label":"platforms: web and Android"},{"value":"₹99","label":"optional plans start at"}],"problems":[{"title":"Too many casual profiles","text":"Most dating apps are built for endless swiping, which makes it hard to find someone who is serious."},{"title":"Hard to know who is real","text":"Without verification, it is difficult to trust the person on the other side of the chat."},{"title":"Indian values are left out","text":"Marriage intent and traditions like Kundli matching rarely have a place in a typical dating app."}],"features":[{"title":"Selfie verification","text":"Meet selfie-verified people, with a blue tick on Pro once verification is approved."},{"title":"Daily picks","text":"A fresh set of people to look at each day, instead of an endless feed."},{"title":"Safe in-app chat","text":"Get to know your match through chat without sharing your number first."},{"title":"Voice and video calls","text":"Talk and see each other inside the app when you are ready."},{"title":"Kundli Gun Milan","text":"See Kundli Gun Milan for a match, built in for those who value it."},{"title":"Play Ludo together","text":"Break the ice with a game of Ludo instead of another hello."},{"title":"Boosts and Super Likes","text":"Reach the top of the deck or stand out to someone you really like."},{"title":"Report and support","text":"Report a member, post or message inside the app. Every complaint is acknowledged within 24 hours."},{"title":"Private by design","text":"Members'' profiles, posts, stories and chats are kept out of search engines."}],"steps":[{"title":"Create your account","text":"Join free on the web or the Android app."},{"title":"Build your profile","text":"Tell people who you are and verify with a selfie."},{"title":"See people and like","text":"Go through your daily picks and like the ones you connect with."},{"title":"Match and talk","text":"Chat, call, check Kundli and play Ludo with your match."}],"audience":["Singles looking for marriage","People who want a serious relationship","Family-minded singles","Anyone tired of casual swiping","Those who value Kundli matching","Singles across India"],"plans":[{"name":"Free","price":"₹0","note":"Free to join and use","items":["Create a profile","See people","Like and match","Chat"]},{"name":"Plus","price":"₹99 / 30 days","note":"Optional upgrade","items":["Unlimited likes","See who liked you","Age filter","1 Boost a week","2 Super Likes a week"]},{"name":"Pro","price":"₹249 / 30 days","note":"Everything in Plus","items":["3 Boosts a week","5 Super Likes a week","Blue tick after selfie verification"]}],"faqs":[{"question":"Is Apnajoda free?","answer":"Yes. Creating a profile, seeing people, liking, matching and chatting are free. Paid plans are optional extras."},{"question":"Where can I use Apnajoda?","answer":"On the web at apnajoda.com and in the Android app."},{"question":"How do I buy Plus or Pro?","answer":"Premium is bought inside the Android app and processed by Google Play. The website does not take payments."},{"question":"Can I cancel my plan?","answer":"Yes. Plans renew every 30 days until you cancel in Google Play. Cancelling stops the next renewal."},{"question":"How do I report someone?","answer":"Use Report inside the app or email info@apnajoda.com. Complaints are acknowledged within 24 hours and resolved within 15 days."}]}', 1, 2);

